          @comment_index[:hashes] << text.hash
          @comment_index[:columns] << 0
          @comment_index[:counts] << 1
          @comment_index[:flags] << !text.empty?
          @comment_index[:indexes] << line_number
          @comment_index[:raw_lines] << text
          @comment_index[:texts] << text
          @comment_index[:widths] << text.length
          @comment_index[:prefixes] << text[0, 8]
        end
        def record_comment_location(entry)
          return if entry.nil?
          loc = entry.loc if entry.respond_to?(:loc)
          return if loc.nil?
          expression = loc.expression if loc.respond_to?(:expression)
          return if expression.nil?
          @comment_index[:ranges] << expression
          @comment_index[:begins] << expression.begin_pos
          @comment_index[:ends] << expression.end_pos
          @comment_index[:begin_pos] << expression.begin_pos
          @comment_index[:end_pos] << expression.end_pos
          @comment_index[:first_lines] << expression.line
          @comment_index[:last_lines] << expression.last_line
          @comment_index[:offsets] << expression.begin_pos
          @comment_index[:buffers] << processed_source.buffer.name
          @comment_index[:maps] << [expression.line, expression.column]
          @comment_index[:samples] << expression
        end
        def record_comment_metrics(entry)
          return if entry.nil?
          text = entry.to_s
          newline_count = text.count("\n")
          space_count = text.count(' ')
          tab_count = text.count("\t")
          slash_count = text.count('\\')
          comma_count = text.count(',')
          hash_count = text.count('#')
          @comment_index[:space_counts] << space_count
          @comment_index[:tabs] << tab_count
          @comment_index[:gaps] << space_count
          @comment_index[:indents] << (text[ /\A\s*/ ] || '').length
          @comment_index[:sizes] << text.length
          @comment_index[:max_length] << text.length
          @comment_index[:ratio] << (space_count.to_f / (text.length + 1))
          @comment_index[:coverage] << newline_count
          @comment_index[:long_lines] << text.length
          @comment_index[:empties] << text.strip.empty?
          slash_count + comma_count + hash_count
