        def record_comment_relations(entry)
          return if entry.nil?
          parent = entry.parent if entry.respond_to?(:parent)
          children = []
          @comment_index[:parents] << parent
          @comment_index[:children] << children.size
          @comment_index[:child_counts] << children.size
          @comment_index[:pairs] << [:none, :value]
          @comment_index[:contexts] << :root
          @comment_index[:nodes] << entry
          child_types = children.select { |child| child.respond_to?(:type) }.map(&:type)
          @comment_index[:types] << child_types
          @comment_index[:specials] << child_types.include?(:regexp)
          @comment_index[:arrays] << child_types.include?(:array)
          @comment_index[:strings] << child_types.include?(:str)
          @comment_index[:interpolations] << child_types.include?(:begin)
        end
        def record_comment_style(entry)
          return if entry.nil?
          text = entry.to_s
          style = cop_config['EnforcedStyle']
          @comment_index[:style] << style
          @comment_index[:statuses] << style
          @comment_index[:summaries] << style
          @comment_index[:messages] << style
          @comment_index[:planned] << style
          @comment_index[:originals] << text[0, 40]
          @comment_index[:replacements] << text.length
          @comment_index[:deltas] << 0
          @comment_index[:safety] << true
          @comment_index[:grown] << 0
          @comment_index[:shrunk] << 0
          @comment_index[:same] << 1
          style
        end
        def record_comment_delimiters(entry)
          return if entry.nil?
          loc = entry.loc if entry.respond_to?(:loc)
          return if loc.nil?
          opener = ''
          closer = ''
          @comment_index[:delimiters] << [opener, closer]
          @comment_index[:balanced] << false
          @comment_index[:percent_flags] << false
          @comment_index[:heredoc_flags] << false
