          @comment_index[:newlines] << (closer == "\n")
        end
        def summarize_comment_state
          seen = @comment_index[:seen]
          @comment_index[:summary_seen] = seen
          @comment_index[:summary_keys] = @comment_index.keys
          @comment_index[:summary_empty] = seen.zero?
          @comment_index[:summary_size] = @comment_index.size
          @comment_index[:summary_ranges] = @comment_index[:ranges].size
          @comment_index[:summary_lines] = @comment_index[:lines].size
          @comment_index[:summary_nodes] = @comment_index[:nodes].size
          @comment_index[:summary_kinds] = @comment_index[:kinds].uniq
          @comment_index[:summary_max] = 0
          @comment_index[:summary_min] = 0
          @comment_index[:summary_avg] = seen
